<?php

declare(strict_types=1);

namespace Sentinel\Services;

use DateTimeImmutable;
use Sentinel\Core\HttpException;
use Sentinel\Core\RuntimeContext;
use Sentinel\Repositories\DeviceAssignmentRepository;

final class DeviceAssignmentManagementService
{
    private const STATUSES=['PLANNED','ACTIVE','ENDED','REVOKED']; private const FIELDS=['employee_id','employee_assignment_id','starts_at','ends_at','assignment_status','returned_at','notes'];
    public function __construct(private readonly DeviceAssignmentRepository $assignments,private readonly RuntimeContext $context,private readonly AuditService $audit){}
    public function listDeviceAssignments(string $deviceId):array{if(!$this->assignments->deviceExists($deviceId))throw HttpException::notFound('Device not found.','device_not_found');return $this->assignments->listForDevice($deviceId);}
    public function assignDevice(string $deviceId,array $input):array{if(!$this->assignments->deviceExists($deviceId))throw HttpException::notFound('Device not found.','device_not_found');$data=$this->fields($input,false);$data['device_id']=(int)$deviceId;$data['assigned_by_user_id']=$this->actor();$data['returned_at']??=null;$this->references($data);$this->dates($data);$this->activeCustody($data);$assignment=$this->assignments->createForCompany($data);$this->audit('assigned',(string)$assignment['device_assignment_id'],[],$assignment);return$assignment;}
    public function updateAssignment(string $id,array $input):array{$before=$this->get($id);$patch=$this->fields($input,true);if($patch===[])throw HttpException::unprocessable('No editable assignment fields were provided.','invalid_device_assignment_update');$effective=array_merge($before,$patch);$this->references($effective);$this->dates($effective);$this->activeCustody($effective,$id);$updated=$this->assignments->updateForCompany($id,$patch)??throw HttpException::notFound('Device assignment not found.','device_assignment_not_found');$this->audit('updated',$id,$before,$updated);return$updated;}
    public function endAssignment(string $id,array $input):array{$before=$this->get($id);if(in_array($before['assignment_status'],['ENDED','REVOKED'],true))throw HttpException::unprocessable('Assignment is already terminal.','invalid_assignment_transition');$endsAt=$this->date($input['ends_at']??null,'ends_at');if($endsAt<$this->date($before['starts_at'],'starts_at'))throw HttpException::unprocessable('Ends at must not precede starts at.','invalid_date_relationship');$updated=$this->assignments->updateForCompany($id,['assignment_status'=>'ENDED','ends_at'=>$input['ends_at'],'returned_at'=>$input['returned_at']??$input['ends_at']])??throw HttpException::notFound('Device assignment not found.','device_assignment_not_found');$this->audit('ended',$id,$before,$updated);return$updated;}
    private function get(string $id):array{return$this->assignments->findByIdForCompany($id)??throw HttpException::notFound('Device assignment not found.','device_assignment_not_found');}
    private function fields(array $input,bool $update):array{if(array_diff(array_keys($input),self::FIELDS)!==[])throw HttpException::unprocessable('Invalid device assignment fields.','invalid_device_assignment_request');$data=$input;foreach(['employee_id','employee_assignment_id']as$f)if(isset($data[$f]))$data[$f]=$this->id($data[$f],$f);foreach(['starts_at','ends_at','returned_at']as$f)if(isset($data[$f])&&$data[$f]!==null)$this->date($data[$f],$f);if(isset($data['assignment_status'])&&!in_array($data['assignment_status'],self::STATUSES,true))throw HttpException::unprocessable('Assignment status is invalid.','invalid_assignment_status');if(isset($data['notes'])&&$data['notes']!==null&&(!is_string($data['notes'])||strlen($data['notes'])>65535))throw HttpException::unprocessable('Assignment notes are invalid.','invalid_assignment_notes');if(!$update){foreach(['employee_id','starts_at']as$f)if(!isset($data[$f]))throw HttpException::unprocessable('Assignment field is required.','invalid_'.$f);$data['assignment_status']??='PLANNED';$data['ends_at']??=null;}return$data;}
    private function references(array $data):void{if(!$this->assignments->employeeExists((string)$data['employee_id']))throw HttpException::notFound('Employee not found.','employee_not_found');if(isset($data['employee_assignment_id'])&&$data['employee_assignment_id']!==null){$assignment=$this->assignments->employeeAssignment((string)$data['employee_assignment_id']);if($assignment===null|| (string)$assignment['employee_id']!==(string)$data['employee_id'])throw HttpException::notFound('Employee assignment not found.','employee_assignment_not_found');}}
    private function dates(array $data):void{$start=$this->date($data['starts_at'],'starts_at');$end=isset($data['ends_at'])&&$data['ends_at']!==null?$this->date($data['ends_at'],'ends_at'):null;if($end!==null&&$end<$start)throw HttpException::unprocessable('Ends at must not precede starts at.','invalid_date_relationship');if(($data['assignment_status']??null)==='ENDED'&&$end===null)throw HttpException::unprocessable('Ended assignments require ends_at.','invalid_ends_at');}
    private function activeCustody(array $data,?string $exclude=null):void{if(($data['assignment_status']??null)==='ACTIVE'&&($data['ends_at']??null)===null){$current=$this->assignments->activeAssignmentForDevice((string)$data['device_id']);if($current!==null&&(string)$current['device_assignment_id']!==$exclude)throw HttpException::conflict('Device already has an active assignment.','device_assignment_conflict');}}
    private function id(mixed $value,string $field):int{if((!is_int($value)&&!(is_string($value)&&ctype_digit($value)))||(int)$value<1)throw HttpException::unprocessable('Assignment identifier is invalid.','invalid_'.$field);return(int)$value;}private function date(mixed $value,string $field):DateTimeImmutable{if(!is_string($value))throw HttpException::unprocessable('Assignment date is invalid.','invalid_'.$field);try{return new DateTimeImmutable($value);}catch(\Throwable){throw HttpException::unprocessable('Assignment date is invalid.','invalid_'.$field);}}private function actor():?string{$user=$this->context->user();return is_scalar($user)?(string)$user:null;}private function audit(string $action,string $id,array $old,array $new):void{try{$this->audit->record('device_assignment',$action,$id,$old,$new);}catch(\Throwable){}}
}